// The street key: the JS twin of the backend's road_key() normalisation.
//
// The backend's held-out street list (services/api/tests/fixtures/
// linz-holdout-streets.txt, generated by scripts/data/split-linz-holdout.py
// 2026-11-08) spells every held-out street as a normalised KEY: lower-case,
// punctuation folded, and the street type folded to its abbreviation, so
// "Bealey Avenue" and "Bealey Ave" are one street exactly the way the D8
// engine sees them.
//
// The voice lane adopted that list as the single shared held-out source
// (founder instruction 2026-11-09, PART B: "ADOPT THE BACKEND'S LIST as the
// single held-out source"), so the voice manifest must compare roads in the
// same key. This module is the one place that mapping lives for the eval
// scripts; it mirrors the Python table (scripts/data/split-linz-holdout.py's
// _STREET_TYPES, which in turn mirrors services/api/app/address_correction.py).
//
// The suffix table is duplicated on purpose: it is a mirror of the Python
// table, and the eval scripts' own test pins the mirror against a sample.

/** The street types and their abbreviations (the Python _STREET_TYPES mirror). */
export const STREET_TYPES = {
  street: 'st',
  st: 'st',
  road: 'rd',
  rd: 'rd',
  avenue: 'ave',
  ave: 'ave',
  drive: 'dr',
  dr: 'dr',
  place: 'pl',
  pl: 'pl',
  crescent: 'cres',
  cres: 'cres',
  terrace: 'tce',
  tce: 'tce',
  lane: 'ln',
  ln: 'ln',
  close: 'cl',
  cl: 'cl',
  court: 'ct',
  ct: 'ct',
  way: 'way',
  grove: 'gr',
  gr: 'gr',
  mews: 'mews',
  quay: 'quay',
  parade: 'pde',
  pde: 'pde',
  highway: 'hwy',
  hwy: 'hwy',
  square: 'sq',
  sq: 'sq',
  esplanade: 'esp',
  esp: 'esp',
  bypass: 'byp',
  byp: 'byp',
  motorway: 'shwy',
  shwy: 'shwy',
};

/**
 * The street key of a road name: the backend's road_key() normalisation.
 *
 * Lower-case, punctuation folded to spaces, the last token folded to its
 * abbreviation when it is a street type. "Bealey Avenue" -> "bealey ave".
 */
export function streetKeyOf(road) {
  const text = road
    .toLowerCase()
    .replace(/[^a-z0-9 ]+/g, ' ')
    .trim();
  const tokens = text.split(/\s+/).filter(Boolean);
  if (tokens.length > 0 && Object.prototype.hasOwnProperty.call(STREET_TYPES, tokens[tokens.length - 1])) {
    tokens[tokens.length - 1] = STREET_TYPES[tokens[tokens.length - 1]];
  }
  return tokens.join(' ');
}

/** The long spellings of the abbreviations, so "bealey ave" also matches "Bealey Avenue". */
const LONG_OF = Object.fromEntries(
  Object.entries(STREET_TYPES)
    .filter(([long, abbr]) => long !== abbr)
    .map(([long, abbr]) => [abbr, long]),
);

/**
 * A case-insensitive source that matches a street key in either spelling:
 * "bealey ave" matches "Bealey Ave" and "Bealey Avenue" (the templates and the
 * parser patterns spell the road the way a courier says it).
 */
export function streetKeyPattern(key) {
  const tokens = key.split(' ');
  const escaped = key.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  if (tokens.length < 2) {
    return escaped;
  }
  const last = tokens[tokens.length - 1];
  const long = LONG_OF[last];
  const suffix = long === undefined ? escaped : `${escaped}|${escaped.replace(/[a-z]+$/, long)}`;
  return suffix;
}
